import numpy as np
from scipy.optimize import minimize

def solve_n(n):
    """
    Finds the maximum of sum(a_i^2) subject to sum(a_i^3) = 0 and |a_i| <= 2/sqrt(n).
    """

    # Objective function: minimize -sum(a_i^2)
    def objective(a):
        return -np.sum(a**2)

    # Equality constraint: sum(a_i^3) = 0
    def constraint_sum_cube(a):
        return np.sum(a**3)

    constraints = ({'type': 'eq', 'fun': constraint_sum_cube})

    # Inequality constraints: |a_i| <= 2/sqrt(n) => a_i - 2/sqrt(n) <= 0 and -a_i - 2/sqrt(n) <= 0
    # We handle these as bounds for simplicity in optimization.
    bound = 2 / np.sqrt(n)
    bounds = [(-bound, bound)] * n

    # Initial guess (a random distribution might work, but let's try a simple one like all zeros)
    # Note: If all zeros is the guess, the constraint sum(a_i^3)=0 is met, and the objective is 0.
    # This is a valid point but likely not the maximum.
    x0 = np.zeros(n)

    # Since the objective is quadratic and constraints are cubic/linear, SLSQP should work.
    try:
        result = minimize(objective, x0, method='SLSQP', bounds=bounds, constraints=constraints)

        if result.success:
            max_sum_sq = -result.fun
            optimal_a = result.x

            # Check if the solution is within the bounds (it should be if bounds were set correctly)
            is_valid = all(abs(a) <= bound + 1e-6 for a in optimal_a)

            return max_sum_sq, optimal_a, is_valid
        else:
            return None, None, False

    except Exception as e:
        return None, None, False

# Test cases
N_values = [2, 3, 4]
results = {}
for n in N_values:
    max_sq, a_opt, valid = solve_n(n)
    results[n] = {'max_sq': max_sq, 'a': a_opt, 'valid': valid}

print("--- Results ---")
for n, res in results.items():
    if res['max_sq'] is not None:
        print(f"N={n}: Max Sum Sq = {res['max_sq']:.4f}, Configuration A = {res['a']}")
    else:
        print(f"N={n}: Optimization failed.")

import numpy as np
from scipy.optimize import minimize
import random

def solve_n_robust(n, num_runs=50):
    """
    Finds the maximum of sum(a_i^2) subject to sum(a_i^3) = 0 and |a_i| <= 2/sqrt(n), 
    running optimization from multiple random starting points.
    """

    def objective(a):
        return -np.sum(a**2)

    def constraint_sum_cube(a):
        return np.sum(a**3)

    constraints = ({'type': 'eq', 'fun': constraint_sum_cube})

    bound = 2 / np.sqrt(n)
    bounds = [(-bound, bound)] * n

    best_max_sq = -np.inf
    best_a = None

    for _ in range(num_runs):
        # Generate a random initial guess within the bounds
        x0 = np.random.uniform(-bound, bound, n)

        try:
            # SLSQP is often good, but L-BFGS-B might also be attempted if bounds are the main focus.
            # Sticking with SLSQP as it handles equality constraints well.
            result = minimize(objective, x0, method='SLSQP', bounds=bounds, constraints=constraints)

            if result.success:
                current_max_sq = -result.fun
                if current_max_sq > best_max_sq:
                    best_max_sq = current_max_sq
                    best_a = result.x
        except Exception:
            continue

    return best_max_sq, best_a

# Test cases
N_values = [2, 3, 4]
results = {}
for n in N_values:
    # Increase runs for stability
    max_sq, a_opt = solve_n_robust(n, num_runs=200)
    results[n] = {'max_sq': max_sq, 'a': a_opt}

print("--- Robust Results ---")
for n, res in results.items():
    if res['max_sq'] is not None and res['max_sq'] > 0:
        # Format output nicely
        a_formatted = [f"{x:.4f}" for x in res['a']]
        print(f"N={n}: Max Sum Sq = {res['max_sq']:.4f}, Configuration A = [{', '.join(a_formatted)}]")
    elif res['max_sq'] is not None and res['max_sq'] <= 0:
        print(f"N={n}: Max Sum Sq = {res['max_sq']:.4f} (Close to zero/Numerical issue)")
    else:
        print(f"N={n}: Optimization failed entirely.")
